			if (den.replace(/^[+-]/, '') === '0') return null;
			let sign = 1;
			if (num[0] === '-') { sign = -sign; num = num.slice(1); }
			if (den[0] === '-') { sign = -sign; den = den.slice(1); }
			num = num.replace(/^0+/, '') || '0';
			den = den.replace(/^0+/, '') || '1';
			if (num === '0') return new Fraction(1, '0', '1', mixed);
