			this.sign = s;
			this.num = n;
			this.den = d;
			this.from = Rational._normalizeFrom(from, n);

			this.isZero = (n === "0");
			this.isInteger = (d === "1");
			this.isFinite = this.isZero || Decimal._denHasOnly2And5(d);
			this.isRepeating = !this.isFinite;
			this.isIrrational = (this.from === "irrational");

			this.value = this.toString();
			
