		//  ★ 不产生 irrational
		// ─────────────────────────────────────────────────────────
		static fromAny(value) {
			try {
				if (value instanceof Rational) return value;
				if (value instanceof Fraction) return Rational._fromFraction(value);
				if (value instanceof RepeatingDecimal) return Rational._fromRepeating(value);

				if (typeof value === "number") {
					if (!Number.isFinite(value)) return null;
					return Rational._fromNumber(value);
				}
				if (typeof value !== "string") return null;

				const text = String(value).trim();
				if (text === "" || text === "undefined" || text === "null" || text === "NaN") return null;

				// 🌟 优先尝试解析普通分数或带分数（比如 "1 2/3" 或 "4/5"）
				// 🌟 1. 优先尝试普通分数或带分数（比如 "1 2/3" 或 "4/5"）
				const frac = Fraction._parse(text);
				if (frac) {
					if (frac.mixed) {
						const mixedInfo = _parseFractionValue(text);
						if (mixedInfo && mixedInfo.kind === 'mixed') {
							const negative = mixedInfo.integer.charAt(0) === '-';
							const intAbs = negative ? mixedInfo.integer.slice(1) : mixedInfo.integer;
							const scaled = Decimal._mulInt(intAbs, mixedInfo.denominator);
							const total = Decimal._addInt(scaled, mixedInfo.numerator);
							const numStr = negative ? '-' + total : total;
							return Rational._fromRaw(numStr, mixedInfo.denominator, "frac");
						}
					}
					return Rational._fromFraction(frac);
				}

				// 🌟 2. 尝试循环小数
				const rep = RepeatingDecimal.fromString(text);
				if (rep) return Rational._fromRepeating(rep);

				// 🌟 3. 尝试纯数字（整数/小数），即使是 "1" 也不会漏网！
				const p = Decimal.parse(text);
				if (p) {
					const den = Decimal._powIntStr("10", String(p.frac.length));
					const num = (p.int + p.frac).replace(/^0+/, "") || "0";
					const from = p.frac === "" ? "int" : "dec";
					return Rational._fromRaw(p.sign < 0 ? "-" + num : num, den, from);
				}
				
				// 🌟 4. 终极兜底：如果连 Decimal 都解析不了，强行尝试用 JS 的 Number 解析！
				const numVal = Number(text);
				if (Number.isFinite(numVal)) {
					return Rational._fromNumber(numVal);
				}

				return null;
			} catch (e) {
				console.error('[Rational.fromAny] ❌ 抛出异常！input =', value, '| error =', e);
				console.error('[Rational.fromAny] 堆栈:', e.stack);
				throw e;
			}
		}

