			const parts = this._toDecimalParts();
			const s = this.sign < 0 ? "-" : "";
			if (parts.repeatPart === "") {
				return s + parts.intPart + "." + parts.decPart;
			}
			const p = Number.isFinite(precision) ? precision : 30;
			const rep = parts.repeatPart;
			let dec = parts.decPart;
			while (dec.length < p) dec += rep;
			dec = dec.slice(0, p);
			return s + parts.intPart + "." + dec;
