		_filterBlocksBySettings(blocks) {
			// ── 分类显隐：自动构造 ──
			const classVisibility = {};
			for (const cat of BlockCategories) {
				classVisibility[cat.key] = this._settings[cat.settingsKey] !== false;
			}

			// ── 其它设置（保持手写）──
			const dynamicVisible = this._settings.showDynamicBlocks !== false;
			const showCount = this._settings.showTagCount === true;
			const unimportantVisible = this._settings.showUnimportantBlocks !== false;
			const experimentalVisible = this._settings.showExperimentalBlocks === true;

			// ═══════════════════════════════════════════════════════
			//  ★ 统一辅助函数
			// ═══════════════════════════════════════════════════════

			// 是否是字符串标签（"---xxx" 或 LABEL 积木）
			const isTag = (block) => {
				if (typeof block === 'string') return true;
				return block && block.blockType === BlockType.LABEL;
			};

			// ★★★ 是否是按钮：优先看 blockType，兼容旧写法 opcode === 'openSettings' ★★★
			const isButton = (block) => {
				if (!block || typeof block !== 'object') return false;
				if (block.blockType === BlockType.BUTTON) return true;
				return false;
			};

			// 取积木分类（用于分类显隐和计数）
			const getBlockClass = (block) => {
				const cls = block?.data?.Class;
				if (cls && classVisibility[cls] !== undefined) return cls;
				return 'All';
			};

			// 判断普通积木是否可见（按钮和标签不在此列）
			const isBlockVisible = (block) => {
				const cls = getBlockClass(block);
				if (!classVisibility[cls]) return false;
				if (!dynamicVisible && block && block.dynamicArgument) return false;
				if (!unimportantVisible && block?.data?.Type === CodeType.Unimportant) return false;
				// ★ 用常量 CodeType.Test 而不是字面量 'Test'
				if (!experimentalVisible && block?.data?.Type === CodeType.Test) return false;
				return true;
			};

			// ═══════════════════════════════════════════════════════
			//  Step 1：暂存 —— 按钮 / 标签 / 可见积木 分别打标
			// ═══════════════════════════════════════════════════════
			const staged = [];
			for (const block of blocks) {
				// ★ 所有按钮一律放行（openSettings / openDocs / 未来的新按钮）
				if (isButton(block)) {
					staged.push({ __isButton: true, __raw: block });
					continue;
				}
				// 标签：打标后暂存
				if (isTag(block)) {
					staged.push({ __isTag: true, __raw: block });
					continue;
				}
				// 普通积木：过滤后暂存
				if (isBlockVisible(block)) {
					staged.push(block);
				}
			}

			// ═══════════════════════════════════════════════════════
			//  Step 2：只保留「后面还有可见积木」的标签
			// ═══════════════════════════════════════════════════════
			const finalResult = [];
			for (let i = 0; i < staged.length; i++) {
				const item = staged[i];

				// 按钮：无条件保留（按钮不属于任何分类的内容，它自己就是内容）
				if (item.__isButton) {
					finalResult.push(item.__raw);
					continue;
				}

				// 普通积木：直接保留
				if (!item.__isTag) {
					finalResult.push(item);
					continue;
				}

				// 标签：往后找，直到下一个标签为止，看有没有「普通可见积木」
				let hasContent = false;
				for (let j = i + 1; j < staged.length; j++) {
					const next = staged[j];
					if (next.__isTag) break;              // 撞到下一个标签，停
					if (next.__isButton) continue;        // ★ 按钮不算"内容"
					hasContent = true;
					break;
				}

				// 只有后面真有积木，才保留这个标签
				if (hasContent) finalResult.push(item.__raw);
			}

			// ═══════════════════════════════════════════════════════
			//  Step 3：分类计数（自动构造 counts / 匹配器）
			// ═══════════════════════════════════════════════════════
			if (showCount) {
				// 反向表：Tag 文案 → 分类 key
				const tagTextToKey = {};
				for (const cat of BlockCategories) {
					tagTextToKey[getTag(cat.key)] = cat.key;
				}

				const getTagClass = (tag) => {
					const text = typeof tag === 'string' ? tag : tag.text;
					if (typeof text !== 'string') return null;
					// 去掉前导 "---" 和尾部 "(数字)"
					const clean = text.replace(/^-+/, '').replace(/\(\d+\)$/, '');
					return tagTextToKey[clean] ?? null;
				};

				// 初始化计数
				const counts = Object.fromEntries(
					BlockCategories.map(c => [c.key, 0])
				);

				// ★ 统计时跳过：标签、按钮、隐藏项
				for (const block of finalResult) {
					if (isTag(block)) continue;
					if (isButton(block)) continue;
					if (block && block.hideFromPalette === true) continue;
					const cls = getBlockClass(block);
					if (counts[cls] !== undefined) counts[cls]++;
				}

				// 改写标签文本，追加计数
				for (let i = 0; i < finalResult.length; i++) {
					const block = finalResult[i];
					if (!isTag(block)) continue;
					const cat = getTagClass(block);
					if (!cat) continue;
					const count = counts[cat] ?? 0;
					const originalText = getTag(cat);
					const newText = `${originalText}(${count})`;
					if (typeof block === 'string') {
						finalResult[i] = `---${newText}`;
					} else {
						finalResult[i] = { ...block, text: newText };
					}
				}
			}

			return finalResult;
		}

		
