			const func = this._norm(args.Func);
			const num = this._norm(args.Number);

			// 🚀 注入缓存
			const result = this._getCachedResult('InvTrig', [func, num], () => {
				const op = new Operator();
				const res = op.InverseTrigonometricFunction(func, num);
				
				// 🛡️ 核心修复：如果反三角函数的计算结果是非整数，强制穿上 Irrational 防弹衣！
				// 防止后续乘以数字时，被 15 位的系统精度无情“截肢”。
				if (res instanceof NumberValue && !res.isError()) {
					const decStr = res.toDecimalString(30); // 拿高精度串
					const parsed = Decimal.parse(decStr);
					
					if (parsed && parsed.frac !== "") {
						// 构造一个极其纯净的 Irrational 对象
						const irr = new Irrational("invTrig", decStr, {
							op: func,
							index: null,
							mainarg: num
						});
						return NumberValue.fromIrrational(irr);
					}
				}
				
				return res;
			});

			return this._finalizeResult(result, util);
