		// ═══════════════════════════════════════════════════════════
		//  特殊积木（无 NumberValue 出口）
		// ═══════════════════════════════════════════════════════════
		LocalScope(args, util) {
			const thread = util.thread;
			const frame = util.stackFrame;

			if (!frame.__mathScopeEntered) {
				frame.__mathScopeEntered = true;
				const enterDepth = thread.stackFrames.length;
				if (!thread.__mathScopes) thread.__mathScopes = [];
				const cur = this._getCurrentSettings(thread);
				thread.__mathScopes.push({
					DecimalValue: cur.DecimalValue,
					HandleErrorMode: cur.HandleErrorMode,
					__enterDepth: enterDepth
				});
				this._ensureThreadScopeHook(thread);
				util.startBranch(1, false);
				return;
			}

			if (!frame.__mathScopeExited) {
				frame.__mathScopeExited = true;
				this._popMathScope(thread);
			}
		}

		TryMathBlock(args, util) {
			const thread = util.thread;
			const stackFrame = util.stackFrame;

			// ★★★ 第一次调用：初始化状态机 ★★★
			if (!stackFrame.tc_status) {
				const tcBlock = thread?.target?.blocks?.getBlock(thread.peekStack());
				const tc_status = {
					stage: "TRY",                    // TRY → CATCH_CHECK → CATCH → DONE
					blockId: thread.peekStack(),     // 记住 try 块的 blockId，用于弹栈定位
					blockInputs: tcBlock?.inputs || {},
					error: null,
					isError: false,
					__prevCmpMode: thread.__mathCmpMode,
					__prevErrorFlag: thread.__mathHasError,
				};
				stackFrame.tc_status = tc_status;
				this._recordCapture(thread, tc_status);

				// 进入 Cmp 模式
				thread.__mathCmpMode = true;
				thread.__mathHasError = false;
			}

			const tc_status = stackFrame.tc_status;

			// ★★★ 检查是否出错：如果出错，跳到第二分支 ★★★
			if (tc_status.isError) {
				tc_status.stage = "CATCH";
				tc_status.isError = false;
				tc_status.error = null;

				// 恢复线程状态
				thread.__mathCmpMode = tc_status.__prevCmpMode;
				thread.__mathHasError = tc_status.__prevErrorFlag;

				// 跳到第二分支
				util.startBranch(2, true);
				return;
			}

			switch (tc_status.stage) {
				case "TRY": {
					// 启动第一分支
					tc_status.stage = "CATCH_CHECK";
					util.startBranch(1, true);
					return;
				}
				case "CATCH_CHECK": {
					// 第一分支执行完毕，检查是否出错
					if (thread.__mathHasError === true) {
						// 出错但没触发弹栈（可能路径没走到 _triggerCapture）
						tc_status.stage = "CATCH";
						thread.__mathHasError = false;
						thread.__mathCmpMode = tc_status.__prevCmpMode;
						util.startBranch(2, true);
						return;
					}
					// 无错误：正常结束
					thread.__mathCmpMode = tc_status.__prevCmpMode;
					thread.__mathHasError = tc_status.__prevErrorFlag;
					tc_status.stage = "DONE";
					delete stackFrame.tc_status;
					this._popCapture(thread);
					return;
				}
				case "CATCH": {
					// 第二分支执行完毕
					tc_status.stage = "DONE";
					delete stackFrame.tc_status;
					this._popCapture(thread);
					return;
				}
				default:
					return;
			}
		}

